examples.code:
import { useEffect, useState } from 'react';

function Reloj() {
  const [segundos, setSegundos] = useState(0);
  useEffect(() => {
    const id = setInterval(() => {
      setSegundos(actual => actual + 1);
    }, 1000);
    return () => clearInterval(id);
  }, []);
  return <p>Tiempo: {segundos} segundos</p>;
}

import { useEffect, useState } from 'react';

function Ciudad() {
  const [ciudad, setCiudad] = useState('Corrientes');
  useEffect(() => {
    document.title = `Clima de ${ciudad}`;
  }, [ciudad]);
  return <button onClick={() => setCiudad('Resistencia')}>
    Ciudad: {ciudad}
  </button>;
}

import { useEffect, useState } from 'react';

function AnchoVentana() {
  const [ancho, setAncho] = useState(window.innerWidth);
  useEffect(() => {
    function actualizar() { setAncho(window.innerWidth); }
    window.addEventListener('resize', actualizar);
    return () => window.removeEventListener('resize', actualizar);
  }, []);
  return <p>Ancho: {ancho}px</p>;
}

import { useEffect, useState } from 'react';

function Usuario({ id }) {
  const [usuario, setUsuario] = useState(null);
  useEffect(() => {
    let ignorar = false;
    async function cargar() {
      const respuesta = await fetch(`https://jsonplaceholder.typicode.com/users/${id}`);
      if (!respuesta.ok) throw new Error('No se pudo cargar el usuario');
      const datos = await respuesta.json();
      if (!ignorar) setUsuario(datos);
    }
    cargar().catch(console.error);
    return () => { ignorar = true; };
  }, [id]);
  return <p>{usuario ? usuario.name : 'Cargando...'}</p>;
}

