import { createContext, useContext } from 'react';

const TemaContext = createContext('claro');

function Boton() {
  const tema = useContext(TemaContext);
  return <button className={`boton-${tema}`}>Guardar</button>;
}

function App() {
  return <TemaContext.Provider value="oscuro">
    <Boton />
  </TemaContext.Provider>;
}

import { createContext, useContext, useState } from 'react';

const IdiomaContext = createContext(null);

function CambiarIdioma() {
  const { idioma, setIdioma } = useContext(IdiomaContext);
  return <button onClick={() => setIdioma(idioma === 'es' ? 'en' : 'es')}>
    Idioma: {idioma}
  </button>;
}

function App() {
  const [idioma, setIdioma] = useState('es');
  return <IdiomaContext.Provider value={{ idioma, setIdioma }}>
    <CambiarIdioma />
  </IdiomaContext.Provider>;
}

const SesionContext = createContext(null);

function useSesion() {
  const sesion = useContext(SesionContext);
  if (sesion === null) {
    throw new Error('useSesion debe utilizarse dentro de SesionProvider');
  }
  return sesion;
}

function UsuarioActual() {
  const { nombre } = useSesion();
  return <p>Conectado: {nombre}</p>;
}

import { createContext, useContext, useMemo, useState } from 'react';

const FiltroContext = createContext(null);
const AccionesFiltroContext = createContext(null);

function FiltroProvider({ children }) {
  const [estado, setEstado] = useState('todos');
  const acciones = useMemo(() => ({
    mostrarTodos: () => setEstado('todos'),
    mostrarLeidos: () => setEstado('leidos')
  }), []);

  return (
    <AccionesFiltroContext.Provider value={acciones}>
      <FiltroContext.Provider value={estado}>
        {children}
      </FiltroContext.Provider>
    </AccionesFiltroContext.Provider>
  );
}

function Resumen() {
  const estado = useContext(FiltroContext);
  return <p>Filtro actual: {estado}</p>;
}

function BotonesFiltro() {
  const acciones = useContext(AccionesFiltroContext);
  return <>
    <button onClick={acciones.mostrarTodos}>Todos</button>
    <button onClick={acciones.mostrarLeidos}>Leídos</button>
  </>;
}
